import type { HTMLAttributes } from "react"
import { cva } from "class-variance-authority"
import { cn } from "cn"
import { composeRenderProps } from "react-aria-components/composeRenderProps"
import {
  GridList as AriaGridList,
  GridListHeader as AriaGridListHeader,
  GridListItem as AriaGridListItem,
  Button,
  type GridListItemProps,
  type GridListProps
} from "react-aria-components/GridList"
import { Checkbox } from "./checkbox"

export function GridList<T>({ children, ...props }: GridListProps<T>) {
  const isHorizontal = (props as { orientation?: "horizontal" | "vertical" }).orientation === "horizontal"
  return (
    <AriaGridList
      {...props}
      className={composeRenderProps(props.className, (className) =>
        cn(
          isHorizontal
            ? "relative flex w-full max-w-125 flex-row flex-nowrap overflow-x-auto rounded-lg border border-neutral-300 bg-white font-sans empty:flex empty:items-center empty:justify-center empty:text-sm empty:italic dark:border-neutral-700 dark:bg-neutral-900"
            : "relative w-50 overflow-auto rounded-lg border border-neutral-300 bg-white font-sans empty:flex empty:items-center empty:justify-center empty:text-sm empty:italic dark:border-neutral-700 dark:bg-neutral-900",
          className
        )
      )}
    >
      {children}
    </AriaGridList>
  )
}

const itemStyles = cva(
  [
    "relative flex cursor-default select-none gap-3 border-transparent px-3 py-2 text-neutral-900 text-sm -outline-offset-2 dark:text-neutral-200",
    "[[data-orientation=vertical]_&]:border-t [[data-orientation=vertical]_&]:first:rounded-t-lg [[data-orientation=vertical]_&]:first:border-t-0 [[data-orientation=vertical]_&]:last:rounded-b-lg [[data-orientation=vertical]_&]:dark:border-t-neutral-700",
    "[[data-orientation=horizontal]_&]:flex-shrink-0 [[data-orientation=horizontal]_&]:border-l [[data-orientation=horizontal]_&]:first:rounded-s-lg [[data-orientation=horizontal]_&]:first:border-l-0 [[data-orientation=horizontal]_&]:last:rounded-e-lg [[data-orientation=horizontal]_&]:dark:border-l-neutral-700"
  ],
  {
    variants: {
      isSelected: {
        false:
          "pressed:bg-neutral-100 hover:bg-neutral-100 dark:pressed:bg-neutral-700/60 dark:hover:bg-neutral-700/60",
        true: [
          "z-20 bg-blue-100 pressed:bg-blue-200 hover:bg-blue-200 dark:bg-blue-700/30 dark:pressed:bg-blue-700/40 dark:hover:bg-blue-700/40",
          "[[data-orientation=vertical]_&]:border-y-blue-200 [[data-orientation=vertical]_&]:dark:border-y-blue-900",
          "[[data-orientation=horizontal]_&]:border-x-blue-200 [[data-orientation=horizontal]_&]:dark:border-x-blue-900"
        ].join(" ")
      },
      isDisabled: {
        true: "z-10 text-neutral-300 dark:text-neutral-600 forced-colors:text-[GrayText]"
      }
    }
  }
)

export function GridListItem({ children, ...props }: GridListItemProps) {
  const textValue = typeof children === "string" ? children : undefined
  return (
    <AriaGridListItem textValue={textValue} {...props} className={itemStyles}>
      {composeRenderProps(children, (children, { selectionMode, selectionBehavior, allowsDragging }) => (
        <>
          {/* Add elements for drag and drop and selection. */}
          {allowsDragging && <Button slot="drag">≡</Button>}
          {selectionMode !== "none" && selectionBehavior === "toggle" && <Checkbox slot="selection" />}
          {children}
        </>
      ))}
    </AriaGridListItem>
  )
}

export function GridListHeader({ children, ...props }: HTMLAttributes<HTMLElement>) {
  return (
    <AriaGridListHeader
      {...props}
      className={cn(
        "z-10 -mt-px border-y border-y-neutral-200 bg-neutral-100/60 px-4 py-1 font-semibold text-neutral-500 text-sm backdrop-blur-md supports-[-moz-appearance:none]:bg-neutral-100 dark:border-y-neutral-700 dark:bg-neutral-700/60 dark:text-neutral-300",
        props.className
      )}
    >
      {children}
    </AriaGridListHeader>
  )
}
